package dev.flatmine.screen;
import net.minecraft.client.gui.DrawContext; import net.minecraft.client.gui.screen.Screen; import net.minecraft.client.gui.widget.ButtonWidget; import net.minecraft.text.Text;
public final class TutorialScreen extends Screen { public TutorialScreen(){super(Text.literal("FLATMINE"));} protected void init(){addDrawableChild(ButtonWidget.builder(Text.literal("Đóng"),b->close()).dimensions(width/2-50,height-40,100,20).build());} public void render(DrawContext c,int mx,int my,float d){c.fill(0,0,width,height,0xE0101010);super.render(c,mx,my,d);c.drawCenteredTextWithShadow(textRenderer,"FLATMINE",width/2,28,0xFFFFFF);String[] l={"1. Cầm Pickaxe hoặc Shovel.","2. Right-click block thứ nhất để chọn góc 1.","3. Right-click block thứ hai để chọn góc 2.","4. Xác nhận để bắt đầu đào.","5. Mod đào từ Y cao xuống Y thấp.","6. X để hủy.","7. K để mở Settings."};for(int i=0;i<l.length;i++)c.drawCenteredTextWithShadow(textRenderer,l[i],width/2,58+i*18,0xF2F2F2);} public boolean shouldPause(){return false;} }
